<template><section class="page"><header><div><h2>物料申请管理</h2><p>审批维修领料并完成库存预留和出库。</p></div></header><el-form class="filters" inline><el-form-item label="状态"><el-select v-model="status" clearable style="width:180px"><el-option v-for="(label,value) in statusLabels" :key="value" :value="value" :label="label"/></el-select></el-form-item><el-form-item><el-button type="primary" @click="search">查询</el-button></el-form-item></el-form><el-table :data="rows" border><el-table-column prop="requestNo" label="申请单号" width="170"/><el-table-column prop="applicantName" label="申请人" width="110"/><el-table-column label="申请物料" min-width="260"><template #default="{row}">{{row.items.map(x=>`${x.materialName} × ${x.requestedQuantity}`).join('；')}}</template></el-table-column><el-table-column label="状态" width="130"><template #default="{row}"><el-tag>{{statusLabels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="申请时间" width="170"><template #default="{row}">{{dateTime(row.createTime)}}</template></el-table-column><AdaptiveActionColumn label="操作" :width="170"><template #default="{row}"><div class="actions"><el-button v-if="row.status==='SUBMITTED'" link type="primary" @click="openReview(row)">审批</el-button><el-button v-if="row.status==='APPROVED'" link type="success" @click="issue(row)">确认出库</el-button></div></template></AdaptiveActionColumn></el-table><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="search"/><el-dialog v-model="dialog" title="物料申请审批" width="640px"><el-table :data="review.items" border><el-table-column prop="materialName" label="物料"/><el-table-column prop="requestedQuantity" label="申请数量" width="110"/><el-table-column label="批准数量" width="180"><template #default="{row}"><el-input-number v-model="row.approvedQuantity" :min="0.001" :max="row.requestedQuantity" :precision="3"/></template></el-table-column></el-table><el-input v-model="review.comment" type="textarea" placeholder="审批意见" style="margin-top:14px"/><template #footer><el-button type="danger" @click="submitReview(false)">驳回</el-button><el-button type="primary" @click="submitReview(true)">批准并预留库存</el-button></template></el-dialog></section></template>
<script setup>
import { onMounted, reactive, ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { issueMaterialRequest, materialRequests, reviewMaterialRequest } from '../api';import { dateTime,statusLabels } from '../labels'
const rows=ref([]),status=ref(''),page=ref(1),size=ref(20),total=ref(0),dialog=ref(false),selected=ref(null);const review=reactive({comment:'',items:[]});const load=async()=>{const r=await materialRequests({status:status.value,page:page.value-1,size:size.value});rows.value=r.data.content;total.value=r.data.totalElements};const search=()=>{page.value=1;load()};const openReview=row=>{selected.value=row;review.comment='';review.items=row.items.map(x=>({...x,approvedQuantity:x.requestedQuantity}));dialog.value=true};const submitReview=async approved=>{await reviewMaterialRequest(selected.value.id,{approved,comment:review.comment,items:review.items.map(x=>({itemId:x.id,approvedQuantity:x.approvedQuantity}))});ElMessage.success(approved?'审批通过':'已驳回');dialog.value=false;load()};const issue=async row=>{await ElMessageBox.confirm('确认物料已经实际发放？确认后将扣减库存。','出库确认');await issueMaterialRequest(row.id);ElMessage.success('出库成功');load()};onMounted(load)
</script><style scoped>.page{padding:24px}header{margin-bottom:18px}h2{margin:0 0 6px}p{margin:0;color:#84909a}.filters{margin-bottom:10px}.el-pagination{margin-top:10px;justify-content:flex-end}.actions{display:flex;flex-wrap:nowrap;white-space:nowrap}</style>
